PORTAL_RENDER = """if(!d||!Array.isArray(d.sensors))return;for(const s of d.sensors){const el=document.querySelector('[data-now="'+s.id+'"]');if(!el||!s.now)continue;let t="";
  if(s.id==="hamilton")t=s.now.set_aside&&s.now.set_aside.length?P.live.hamilton_set.replace("{x}",s.now.set_aside.map((x)=>P.names[x]||x).join(", ")):P.live.hamilton_ok;
  else if(s.id==="mikrin")t=s.now.minutes!=null?P.live.mikrin.replace("{x}",s.now.minutes+" "+P.min):P.live.mikrin_none;
  else if(s.id==="duckworth")t=s.now.rhythm_effect==null?P.live.collecting:P.live.duckworth.replace("{x}",s.now.rhythm_effect);
  else if(s.id==="trevisan")t=s.now.enough==null?P.live.collecting:P.live.trevisan.replace("{k}",s.now.enough).replace("{n}",s.now.of);
  else if(s.id==="bertsekas")t=!s.now.tools?P.live.collecting:P.live.bertsekas.replace("{n}",s.now.tools);
  else if(s.id==="simpson")t=s.now.change==null?P.live.collecting:P.live.simpson.replace("{c}",(s.now.change>0?"+":"")+s.now.change).replace("{w}",(s.now.within>0?"+":"")+s.now.within);
  else if(s.id==="frege")t=s.now.verdict==="collecting"&&!s.now.names?P.live.collecting:P.live.frege.replace("{n}",s.now.names).replace("{a}",s.now.ambiguous);
  else if(s.id==="harman")t=s.now.verdict==="collecting"&&!s.now.resolved?P.live.collecting:P.live.harman.replace("{n}",s.now.resolved).replace("{w}",s.now.waiting);
  else if(s.id==="cohen")t=!s.now.checks?P.live.collecting:P.live.cohen.replace("{b}",s.now.blind).replace("{n}",s.now.checks);
  else if(s.id==="pearson")t=s.now.verdict==="collecting"?P.live.collecting:P.live.pearson.replace("{n}",s.now.answers).replace("{a}",s.now.false_alarms).replace("{m}",s.now.misses);
  else if(s.id==="pareto")t=s.now.index_top20==null||s.now.verdict==="collecting"?P.live.collecting:P.live.pareto.replace("{x}",Math.round(100*s.now.index_top20)+" %");
  else if(s.id==="newcomb")t=s.now.verdict==="collecting"?P.live.collecting:P.live.newcomb.replace("{n}",s.now.numbers).replace("{m}",s.now.mad);
  else if(s.id==="kasperson")t=s.now.verdict==="collecting"?P.live.collecting:P.live.kasperson.replace("{a}",s.now.amplified).replace("{n}",s.now.stories);
  else if(s.id==="searle")t=s.now.not_yet_pct==null?P.live.collecting:P.live.searle.replace("{x}",s.now.not_yet_pct);
  else if(s.id==="rabin")t=!s.now.checks?P.live.collecting:P.live.rabin.replace("{n}",s.now.checks).replace("{x}",s.now.differs_pct??"—");
  else if(s.id==="frankfurt")t=s.now.checkable_pct==null?P.live.collecting:P.live.frankfurt.replace("{c}",s.now.checkable_pct).replace("{x}",s.now.nothing_to_check_pct);
  else if(s.id==="hagenauer")t=s.now.total==null?P.live.collecting:P.live.hagenauer.replace("{e}",s.now.on_edge).replace("{n}",s.now.total);
  else if(s.id==="lyberg")t=s.now.regions_not_seen==null?P.live.collecting:P.live.lyberg.replace("{n}",s.now.regions_not_seen).replace("{s}",s.now.silent);
  else if(s.id==="baird")t=s.now.total==null?P.live.collecting:P.live.baird.replace("{t}",s.now.traced).replace("{n}",s.now.total);
  else if(s.id==="leamer")t=s.now.value==null?P.live.collecting:P.live.leamer.replace("{v}",s.now.value).replace("{lo}",s.now.low).replace("{hi}",s.now.high);
  else if(s.id==="howard")t=s.now.verdict==="collecting"||s.now.p_confirm==null?P.live.collecting:P.live.howard.replace("{x}",s.now.p_confirm);
  else if(s.id==="halpern")t=s.now.verdict==="collecting"?P.live.collecting:s.now.verdict==="explained"||s.now.verdict==="partly"?P.live.halpern.replace("{n}",s.now.causes):P.live.halpern_none;
  else if(s.id==="kahneman")t=s.now.system_noise!=null?P.live.kahneman.replace("{x}",s.now.system_noise):P.live.collecting;
  else if(s.id==="ziv")t=s.now.novelty_all!=null?P.live.ziv.replace("{x}",s.now.novelty_all):P.live.collecting;
  else if(s.id==="cox")t=s.now.median_hours_all!=null?P.live.cox.replace("{x}",s.now.median_hours_all):P.live.collecting;
  else if(s.id==="park")t=P.live.park.replace("{n}",s.now.checked).replace("{m}",s.now.with_signs);
  else if(s.id==="polyak")t=s.now.moving&&s.now.moving.length?P.live.polyak_move.replace("{x}",s.now.moving.map((m)=>(P.names[m.id]||m.id)+" "+(m.direction==="up"?"↑":"↓")).join(", ")):P.live.polyak_calm;
  el.textContent=P.now+": "+t;}"""
