_ST = {"ru": dict(a={"event":"событие","claim":"заявление","promise":"обещание или план","threat":"угроза или предупреждение","demand":"требование или призыв"}, row="заявлений {c}, обещаний {p}, угроз {t}, требований {d}", sum="Заголовков: {n}. Ещё не случилось — {x} %. Событие {e} %, заявление {c} %, обещание {p} %, угроза {t} %, требование {d} %."),
  "de": dict(a={"event":"Ereignis","claim":"Aussage","promise":"Versprechen oder Plan","threat":"Drohung oder Warnung","demand":"Forderung oder Appell"}, row="Aussagen {c}, Versprechen {p}, Drohungen {t}, Forderungen {d}", sum="Schlagzeilen: {n}. Noch nicht geschehen: {x} %. Ereignis {e} %, Aussage {c} %, Versprechen {p} %, Drohung {t} %, Forderung {d} %."),
  "en": dict(a={"event":"event","claim":"claim","promise":"promise or plan","threat":"threat or warning","demand":"demand or call"}, row="claims {c}, promises {p}, threats {t}, demands {d}", sum="Headlines: {n}. Not happened yet: {x} %. Event {e} %, claim {c} %, promise {p} %, threat {t} %, demand {d} %.")}
_mk("searle", SEARLE_RENDER, {"@type": "Person", "name": "John Searle", "sameAs": ["https://en.wikipedia.org/wiki/John_Searle"]}, {
 "ru": _L("ru", "searle", "Датчик Сёрл · Orb Studio", "Случилось ли это — или пока только обещание, угроза или требование? Речевой акт каждого заголовка радаров. Назван в честь Джона Сёрла (1932–2025).", "Датчик Сёрл",
   "«Пригрозил пошлинами» — не значит «ввёл пошлины». Датчик определяет, что сообщает каждый заголовок радаров: совершившееся событие, чьё-то заявление, обещание или план, угрозу или предупреждение, требование или призыв — и показывает, какая доля новостей ещё не случилась. Без ИИ, по словам на трёх языках.",
   "В честь Джона Сёрла (1932–2025)", 'Джон Сёрл — американский философ, профессор Калифорнийского университета в Беркли. Развил теорию речевых актов: утверждать, обещать, угрожать, просить — это разные действия словами, и у каждого свои условия. Известен и мысленным экспериментом «китайская комната» о том, понимает ли машина смысл. <a href="{wiki}" rel="noopener">' + W["ru"] + '</a>.',
   "Датчик назван в его честь; Orb Studio не связана с Джоном Сёрлом, его семьёй или Калифорнийским университетом.", "Событие или только слова",
   dict(**_ST["ru"])),
 "de": _L("de", "searle", "Searle-Sensor · Orb Studio", "Ist es passiert – oder nur ein Versprechen, eine Drohung, eine Forderung? Der Sprechakt jeder Radar-Schlagzeile. Benannt nach John Searle (1932–2025).", "Searle-Sensor",
   "„Droht mit Zöllen“ heißt nicht „führt Zölle ein“. Der Sensor bestimmt, was jede Radar-Schlagzeile meldet: ein geschehenes Ereignis, eine Aussage, ein Versprechen oder einen Plan, eine Drohung oder Warnung, eine Forderung oder einen Appell – und zeigt, welcher Anteil der Nachrichten noch nicht geschehen ist. Ohne KI, nach Wörtern in drei Sprachen.",
   "Zu Ehren von John Searle (1932–2025)", 'John Searle war ein US-amerikanischer Philosoph und Professor an der University of California, Berkeley. Er entwickelte die Sprechakttheorie: behaupten, versprechen, drohen, bitten sind verschiedene Handlungen mit Worten, jede mit eigenen Bedingungen. Bekannt ist auch sein Gedankenexperiment „Chinesisches Zimmer“ zur Frage, ob eine Maschine Bedeutung versteht. <a href="{wiki}" rel="noopener">' + W["de"] + '</a>.',
   "Der Sensor ist nach ihm benannt; Orb Studio steht in keiner Verbindung zu John Searle, seiner Familie oder der University of California.", "Ereignis oder nur Worte",
   dict(**_ST["de"])),
 "en": _L("en", "searle", "Searle sensor · Orb Studio", "Did it happen – or is it only a promise, a threat or a demand? The speech act of every radar headline. Named in honour of John Searle (1932–2025).", "Searle sensor",
   "“Threatens tariffs” does not mean “imposed tariffs”. The sensor labels what each radar headline reports: an event that happened, someone's claim, a promise or plan, a threat or warning, a demand or call – and shows what share of the news has not happened yet. No AI, word rules in three languages.",
   "In honour of John Searle (1932–2025)", 'John Searle was an American philosopher and professor at the University of California, Berkeley. He developed the theory of speech acts: asserting, promising, threatening and requesting are different acts done with words, each with its own conditions. He is also known for the “Chinese room” thought experiment on whether a machine understands meaning. <a href="{wiki}" rel="noopener">' + W["en"] + '</a>.',
   "The sensor is named in his honour; Orb Studio is not connected with John Searle, his family or the University of California.", "Event or only words",
   dict(**_ST["en"]))},
 {"ru": ("Джон Сёрл (1932–2025), философия языка и сознания", "Речевые акты: утверждение, обещание, угроза и требование — разные действия; обещание не событие.", "исследовательские классификаторы речевых актов для твитов (Tweet Acts, MIT 2016) и для поиска слухов (2019)", "живые метки для новостных заголовков на трёх языках, добавленные в каждый ответ check_headline", "случилось ли это или пока только слова"),
  "de": ("John Searle (1932–2025), Sprach- und Bewusstseinsphilosophie", "Sprechakte: Behauptung, Versprechen, Drohung und Forderung sind verschiedene Handlungen; ein Versprechen ist kein Ereignis.", "Sprechakt-Klassifikatoren der Forschung für Tweets (Tweet Acts, MIT 2016) und zur Gerüchteerkennung (2019)", "Live-Etiketten für Nachrichtenschlagzeilen in drei Sprachen, in jeder check_headline-Antwort", "ob es passiert ist oder nur Worte sind"),
  "en": ("John Searle (1932–2025), philosophy of language and mind", "Speech acts: asserting, promising, threatening and demanding are different acts; a promise is not an event.", "research speech-act classifiers for tweets (Tweet Acts, MIT 2016) and for rumour detection (2019)", "live labels for news headlines in three languages, added to every check_headline answer", "whether it happened or is only words")},
 {"ru": "Датчик Сёрл", "de": "Searle-Sensor", "en": "Searle sensor"})

