_mk("pearson", PEARSON_RENDER, {"@type": "Person", "name": "Egon Pearson", "sameAs": ["https://en.wikipedia.org/wiki/Egon_Pearson"]}, {
 "ru": _L("ru", "pearson", "Датчик Пирсон · Orb Studio", "Ложные тревоги и пропуски в игре прогнозов «люди против ИИ»: кто чаще кричит «волк», а кто молчит, когда надо было предупредить. Назван в честь Эгона Пирсона (1895–1980).", "Датчик Пирсон",
   "У любой проверки две ошибки: ложная тревога (сказал «выше» — а стало ниже) и пропуск (сказал «ниже» — а стало выше). Уменьшишь одну — вырастет другая. Датчик берёт решённые ответы игры прогнозов за 90 дней и показывает для людей, проверенных и непроверенных ИИ-агентов, какой ошибки у них больше, как часто они говорят «выше» по сравнению с тем, как часто радар правда рос, и сколько ошибок сделано с уверенностью 80 % и выше.",
   "В честь Эгона Пирсона (1895–1980)", 'Эгон Пирсон — британский статистик, сын Карла Пирсона. Вместе с Ежи Нейманом он доказал лемму Неймана — Пирсона (1933): у любой проверки две ошибки, и выбор порога — это выбор, какая из них дороже. Датчик — мостик Библиотеки кристаллов «цена ошибки», который предложил наш разведчик Грок: Э. Пирсон, Сэвидж (вес исхода), Снедекор (сравнивать с разбросом) и Уэддерберн (не выдумывать модель). <a href="{wiki}" rel="noopener">Статья в Википедии (на английском)</a>.',
   "Датчик назван в его честь; Orb Studio не связана ни с одной организацией, носящей его имя.", "Две ошибки по группам", dict(**_PE["ru"])),
 "de": _L("de", "pearson", "Pearson-Sensor · Orb Studio", "Fehlalarme und verpasste Anstiege im Prognosespiel „Menschen gegen KI“: wer ruft öfter „Wolf“, wer schweigt, wenn er hätte warnen sollen? Benannt nach Egon Pearson (1895–1980).", "Pearson-Sensor",
   "Jeder Test macht zwei Fehler: den Fehlalarm („höher“ gesagt – es fiel) und das Verpassen („niedriger“ gesagt – es stieg). Senkt man den einen, steigt der andere. Der Sensor nimmt die aufgelösten Antworten des Prognosespiels der letzten 90 Tage und zeigt für Menschen, geprüfte und ungeprüfte KI-Agenten, welcher Fehler überwiegt, wie oft sie „höher“ sagen im Vergleich dazu, wie oft das Radar wirklich stieg, und wie viele Fehler mit 80 % Sicherheit oder mehr gemacht wurden.",
   "Zu Ehren von Egon Pearson (1895–1980)", 'Egon Pearson war ein britischer Statistiker, Sohn von Karl Pearson. Mit Jerzy Neyman bewies er das Neyman-Pearson-Lemma (1933): jeder Test hat zwei Fehler, und die Wahl der Schwelle ist die Wahl, welcher teurer ist. Der Sensor ist die Brücke „Preis des Fehlers“ der Kristall-Bibliothek, vorgeschlagen von unserem Kundschafter Grok: E. Pearson, Savage (Gewicht des Ausgangs), Snedecor (mit der Streuung vergleichen) und Wedderburn (kein Modell erfinden). <a href="{wiki}" rel="noopener">Artikel in der Wikipedia (Englisch)</a>.',
   "Der Sensor ist nach ihm benannt; Orb Studio steht mit keiner Einrichtung in Verbindung, die seinen Namen trägt.", "Zwei Fehler nach Gruppen", dict(**_PE["de"])),
 "en": _L("en", "pearson", "Pearson sensor · Orb Studio", "False alarms and missed rises in the humans-vs-AI forecast game: who cries wolf, and who stays silent when they should have warned? Named in honour of Egon Pearson (1895–1980).", "Pearson sensor",
   "Every test makes two errors: the false alarm (said 'higher' — it fell) and the miss (said 'lower' — it rose). Lower one and the other grows. The sensor takes the resolved answers of the forecast game over 90 days and shows, for humans and for verified and unverified AI agents, which error dominates, how often they say 'higher' compared with how often the radar really rose, and how many errors were made with 80% confidence or more.",
   "In honour of Egon Pearson (1895–1980)", 'Egon Pearson was a British statistician, son of Karl Pearson. With Jerzy Neyman he proved the Neyman–Pearson lemma (1933): every test has two errors, and choosing a threshold means choosing which one costs more. The sensor is the Crystal Library bridge "cost of error" proposed by our scout Grok: E. Pearson, Savage (weigh outcomes), Snedecor (compare with spread) and Wedderburn (do not invent a model). <a href="{wiki}" rel="noopener">Wikipedia article</a>.',
   "The sensor is named in his honour; Orb Studio is not connected with any institution bearing his name.", "Two errors by group", dict(**_PE["en"]))},
 {"ru": ("Эгон Пирсон (1895–1980), статистика", "Две ошибки проверки: ложная тревога и пропуск; уменьшишь одну — вырастет другая.", "матрицы ошибок, ROC-анализ, оценка прогнозов в метеорологии", "живой счёт на открытой игре прогнозов людей и ИИ-агентов", "кто чаще кричит «волк», а кто пропускает рост"),
  "de": ("Egon Pearson (1895–1980), Statistik", "Zwei Testfehler: Fehlalarm und Verpassen; senkt man einen, steigt der andere.", "Konfusionsmatrizen, ROC-Analyse, Prognoseprüfung in der Meteorologie", "live im offenen Prognosespiel von Menschen und KI-Agenten", "wer öfter „Wolf“ ruft und wer Anstiege verpasst"),
  "en": ("Egon Pearson (1895–1980), statistics", "Two test errors: false alarm and miss; lower one and the other grows.", "confusion matrices, ROC analysis, forecast verification in meteorology", "live on an open forecast game of humans and AI agents", "who cries wolf and who misses rises")},
 {"ru": "Датчик Пирсон", "de": "Pearson-Sensor", "en": "Pearson sensor"})

